return {api_version=1,id="OG_174",name="Faceless Shambler",text="<b>Taunt</b>\n<b>Battlecry:</b> Copy a friendly minion's Attack and Health.",set="OG",type="minion",rarity="epic",cost=4,attack=1,health=1,keywords={"taunt","battlecry"},target_mode="required_if_available",targets=function(ctx,self)return ctx:friendly_minions(self)end,on_battlecry=function(ctx,self,target)if target then local e=ctx:entity(target);cardlib.effects.modify(ctx, self,{stat="attack",operation="set",value=e.attack});ctx:set_health(self,e.health)end end}
